package domain

import "fmt"

// Status is a ticket's position in the support workflow.
type Status string

const (
	StatusOpen       Status = "OPEN"
	StatusInProgress Status = "IN_PROGRESS"
	StatusClosed     Status = "CLOSED"
)

// ErrInvalidTransition reports a status change the workflow forbids.
type ErrInvalidTransition struct {
	From Status
	To   Status
}

func (e ErrInvalidTransition) Error() string {
	return fmt.Sprintf("invalid transition %s -> %s", e.From, e.To)
}

// allowed encodes the workflow. CLOSED is terminal.
var allowed = map[Status][]Status{
	StatusOpen:       {StatusInProgress, StatusClosed},
	StatusInProgress: {StatusOpen, StatusClosed},
	StatusClosed:     {},
}

// CanTransition reports whether from -> to is permitted by the workflow.
func CanTransition(from, to Status) bool {
	for _, candidate := range allowed[from] {
		if candidate == to {
			return true
		}
	}
	return false
}

// Transition validates a status change, returning ErrInvalidTransition if the
// workflow forbids it. Rules live here, not in the HTTP handler.
func Transition(from, to Status) error {
	if !CanTransition(from, to) {
		return ErrInvalidTransition{From: from, To: to}
	}
	return nil
}

package domain

import "testing"

func TestValidTransitions(t *testing.T) {
	for _, tc := range []struct{ from, to Status }{
		{StatusOpen, StatusInProgress},
		{StatusOpen, StatusClosed},
		{StatusInProgress, StatusOpen},
		{StatusInProgress, StatusClosed},
	} {
		if err := Transition(tc.from, tc.to); err != nil {
			t.Errorf("%s -> %s should be allowed, got %v", tc.from, tc.to, err)
		}
	}
}

func TestClosedIsTerminal(t *testing.T) {
	for _, to := range []Status{StatusOpen, StatusInProgress, StatusClosed} {
		if err := Transition(StatusClosed, to); err == nil {
			t.Errorf("CLOSED -> %s must be rejected", to)
		}
	}
}
